const grammarLessons=[{"level": "A1", "title": {"en": "Verb in position two", "az": "Fel ikinci yerdə"}, "rule": {"en": "In a statement, the conjugated verb is the second element. A time phrase can come first; the subject then follows the verb.", "az": "Nəqli cümlədə təsriflənmiş fel ikinci yerdə olur. Cümlə zaman ifadəsi ilə başlayanda mübtəda feldən sonra gəlir."}, "examples": [{"de": "Heute kaufe ich Brot.", "en": "Today I am buying bread.", "az": "Bu gün çörək alıram."}, {"de": "Am Samstag arbeitet meine Schwester.", "en": "My sister works on Saturday.", "az": "Bacım şənbə günü işləyir."}]}, {"level": "A1", "title": {"en": "Articles and accusative", "az": "Artikllər və Akkusativ"}, "rule": {"en": "Learn nouns with der, die or das. A masculine direct object changes der to den and ein to einen; die and das stay the same.", "az": "İsmi der, die və ya das artikli ilə öyrən. Birbaşa tamamlıq olan kişi cinsli isimdə der → den, ein → einen olur; die və das dəyişmir."}, "examples": [{"de": "Ich brauche einen Stift.", "en": "I need a pen.", "az": "Mənə qələm lazımdır."}, {"de": "Sie öffnet die Tür.", "en": "She opens the door.", "az": "O, qapını açır."}]}, {"level": "A1", "title": {"en": "Questions", "az": "Sual cümlələri"}, "rule": {"en": "Yes/no questions begin with the verb. In a question with wo, wann or warum, the verb follows the question word.", "az": "Bəli/xeyr cavabı tələb edən suallar fellə başlayır. Wo, wann və warum ilə başlayan suallarda fel sual sözündən sonra gəlir."}, "examples": [{"de": "Kommst du heute?", "en": "Are you coming today?", "az": "Bu gün gəlirsən?"}, {"de": "Wann beginnt der Film?", "en": "When does the film start?", "az": "Film nə vaxt başlayır?"}]}, {"level": "A1", "title": {"en": "Separable verbs", "az": "Ayrılan fellər"}, "rule": {"en": "In a main clause, the conjugated part is second and the separable prefix goes at the end.", "az": "Baş cümlədə felin təsriflənmiş hissəsi ikinci, ayrılan ön şəkilçisi isə sonuncu yerdə olur."}, "examples": [{"de": "Ich rufe dich nach der Arbeit an.", "en": "I will call you after work.", "az": "İşdən sonra sənə zəng edəcəyəm."}, {"de": "Der Zug fährt um acht Uhr ab.", "en": "The train leaves at eight.", "az": "Qatar saat səkkizdə yola düşür."}]}, {"level": "A1", "title": {"en": "Negation: nicht and kein", "az": "İnkar: nicht və kein"}, "rule": {"en": "Use kein to negate an indefinite noun. Use nicht to negate a verb, adjective or a specific part of a sentence.", "az": "Qeyri-müəyyən ismi inkar etmək üçün kein işlət. Feli, sifəti və ya cümlənin müəyyən hissəsini inkar etmək üçün nicht işlət."}, "examples": [{"de": "Ich habe kein Auto.", "en": "I do not have a car.", "az": "Maşınım yoxdur."}, {"de": "Der Kaffee ist nicht heiß.", "en": "The coffee is not hot.", "az": "Qəhvə isti deyil."}]}, {"level": "A2", "title": {"en": "Perfect tense", "az": "Perfekt zamanı"}, "rule": {"en": "Use haben or sein plus a past participle. Many changes of location use sein. The participle comes at the end of a main clause.", "az": "Haben və ya sein köməkçi feli ilə Partizip II işlənir. Məkan dəyişməsini bildirən bir çox fel sein ilə işlənir. Partizip II baş cümlənin sonunda gəlir."}, "examples": [{"de": "Wir sind gestern nach Köln gefahren.", "en": "We travelled to Cologne yesterday.", "az": "Dünən Kölnə getdik."}, {"de": "Ich habe meine Schlüssel gefunden.", "en": "I found my keys.", "az": "Açarlarımı tapdım."}]}, {"level": "A2", "title": {"en": "Two-way prepositions", "az": "İki hal ilə işlənən sözönülər"}, "rule": {"en": "With in, an and auf, use dative for location and accusative for a destination. Movement alone does not automatically mean accusative.", "az": "In, an və auf ilə məkanı bildirəndə Dativ, istiqaməti bildirəndə Akkusativ işlənir. Hərəkət olması həmişə Akkusativ demək deyil."}, "examples": [{"de": "Das Bild hängt an der Wand.", "en": "The picture is hanging on the wall.", "az": "Şəkil divardan asılıb."}, {"de": "Ich hänge das Bild an die Wand.", "en": "I am hanging the picture on the wall.", "az": "Şəkli divardan asıram."}]}, {"level": "A2", "title": {"en": "Because and that", "az": "Weil və dass"}, "rule": {"en": "In a clause introduced by weil or dass, the conjugated verb goes to the end.", "az": "Weil və ya dass ilə başlayan budaq cümlədə təsriflənmiş fel sona keçir."}, "examples": [{"de": "Ich bleibe zu Hause, weil ich krank bin.", "en": "I am staying home because I am ill.", "az": "Xəstə olduğum üçün evdə qalıram."}, {"de": "Sie sagt, dass der Bus später kommt.", "en": "She says the bus will arrive later.", "az": "O deyir ki, avtobus daha gec gələcək."}]}, {"level": "A2", "title": {"en": "Dative verbs", "az": "Dativ tələb edən fellər"}, "rule": {"en": "Helfen, danken and gehören take a dative object. Learn the case with the verb.", "az": "Helfen, danken və gehören felləri Dativ tələb edir. Feli hansı hal ilə işləndiyi ilə birlikdə öyrən."}, "examples": [{"de": "Kannst du mir kurz helfen?", "en": "Can you help me for a moment?", "az": "Mənə bir anlıq kömək edə bilərsən?"}, {"de": "Die Tasche gehört meiner Freundin.", "en": "The bag belongs to my friend.", "az": "Çanta rəfiqəmə məxsusdur."}]}, {"level": "A2", "title": {"en": "Comparisons", "az": "Müqayisə"}, "rule": {"en": "Use comparative + als for differences and so ... wie for equality. Gut becomes besser.", "az": "Fərqi bildirmək üçün sifətin müqayisə dərəcəsi + als, bərabərliyi bildirmək üçün so ... wie işlənir. Gut sözünün müqayisə forması besser-dir."}, "examples": [{"de": "Der Zug ist schneller als der Bus.", "en": "The train is faster than the bus.", "az": "Qatar avtobusdan daha sürətlidir."}, {"de": "Diese Wohnung ist so groß wie unsere.", "en": "This flat is as large as ours.", "az": "Bu mənzil bizimki qədər böyükdür."}]}, {"level": "B1", "title": {"en": "Relative clauses", "az": "Təyin budaq cümlələri"}, "rule": {"en": "A relative pronoun takes its gender and number from the noun it describes; its case depends on its role inside the relative clause.", "az": "Nisbi əvəzliyin cinsi və sayı aid olduğu isimdən, halı isə budaq cümlədəki vəzifəsindən asılıdır."}, "examples": [{"de": "Das ist der Kollege, dem ich geholfen habe.", "en": "That is the colleague I helped.", "az": "Bu, kömək etdiyim həmkarımdır."}, {"de": "Ich lese das Buch, das du empfohlen hast.", "en": "I am reading the book you recommended.", "az": "Tövsiyə etdiyin kitabı oxuyuram."}]}, {"level": "B1", "title": {"en": "Unreal conditions", "az": "Real olmayan şərtlər"}, "rule": {"en": "Use Konjunktiv II for imagined situations: hätte, wäre or würde + infinitive. It can also make requests polite.", "az": "Xəyali vəziyyətlər üçün Konjunktiv II işlənir: hätte, wäre və ya würde + məsdər. Nəzakətli xahişlərdə də istifadə olunur."}, "examples": [{"de": "Wenn ich mehr Zeit hätte, würde ich öfter kochen.", "en": "If I had more time, I would cook more often.", "az": "Daha çox vaxtım olsaydı, daha tez-tez yemək bişirərdim."}, {"de": "Könnten Sie das bitte wiederholen?", "en": "Could you please repeat that?", "az": "Zəhmət olmasa, bunu təkrar edə bilərsiniz?"}]}, {"level": "B1", "title": {"en": "Verbs with prepositions", "az": "Sözönülü fellər"}, "rule": {"en": "Learn the whole unit: warten auf + accusative, teilnehmen an + dative, sich interessieren für + accusative.", "az": "Birləşməni bütöv öyrən: warten auf + Akkusativ, teilnehmen an + Dativ, sich interessieren für + Akkusativ."}, "examples": [{"de": "Ich warte auf eine Antwort.", "en": "I am waiting for a reply.", "az": "Cavab gözləyirəm."}, {"de": "Sie nimmt an einem Kurs teil.", "en": "She is attending a course.", "az": "O, kursda iştirak edir."}]}, {"level": "B1", "title": {"en": "Purpose: um ... zu", "az": "Məqsəd: um ... zu"}, "rule": {"en": "Use um ... zu when both actions have the same subject. Use damit when you need to state a different subject.", "az": "Hər iki hərəkətin icraçısı eynidirsə, um ... zu işlət. Fərqli icraçını göstərmək lazım gələndə damit işlənir."}, "examples": [{"de": "Ich fahre früher los, um pünktlich anzukommen.", "en": "I leave earlier to arrive on time.", "az": "Vaxtında çatmaq üçün daha tez yola çıxıram."}, {"de": "Ich spreche langsam, damit du mich verstehst.", "en": "I speak slowly so that you understand me.", "az": "Məni başa düşəsən deyə yavaş danışıram."}]}, {"level": "B1", "title": {"en": "Process passive", "az": "Proses bildirən məchul növ"}, "rule": {"en": "Use werden + past participle to focus on what happens to something. The person doing it can be introduced with von + dative.", "az": "Hadisəni və ya prosesi önə çəkmək üçün werden + Partizip II işlənir. Hərəkəti edən şəxs von + Dativ ilə göstərilə bilər."}, "examples": [{"de": "Die Straße wird nächste Woche repariert.", "en": "The road will be repaired next week.", "az": "Yol gələn həftə təmir olunacaq."}, {"de": "Das Paket wurde gestern geliefert.", "en": "The parcel was delivered yesterday.", "az": "Bağlama dünən çatdırıldı."}]}, {"level": "B2", "title": {"en": "Concession and contrast", "az": "Güzəşt və qarşılaşdırma"}, "rule": {"en": "Obwohl introduces a verb-final clause. Trotzdem connects main clauses and occupies a position, so the verb follows it.", "az": "Obwohl ilə başlayan budaq cümlədə fel sonda olur. Trotzdem baş cümlədə birinci yerdədirsə, fel ondan dərhal sonra gəlir."}, "examples": [{"de": "Obwohl es regnete, fand das Konzert statt.", "en": "Although it rained, the concert took place.", "az": "Yağış yağsa da, konsert baş tutdu."}, {"de": "Es regnete. Trotzdem kamen viele Besucher.", "en": "It was raining. Nevertheless, many visitors came.", "az": "Yağış yağırdı. Buna baxmayaraq, çoxlu ziyarətçi gəldi."}]}, {"level": "B2", "title": {"en": "Past unreal conditions", "az": "Keçmişə aid real olmayan şərtlər"}, "rule": {"en": "Use hätte or wäre + past participle to imagine a different past.", "az": "Keçmişdə baş verməyən hadisəni təsəvvür etmək üçün hätte və ya wäre + Partizip II işlənir."}, "examples": [{"de": "Wenn ich früher losgefahren wäre, hätte ich den Zug erreicht.", "en": "If I had left earlier, I would have caught the train.", "az": "Daha tez yola çıxsaydım, qatara çatardım."}, {"de": "Ohne deine Hilfe hätte ich den Fehler nicht bemerkt.", "en": "Without your help, I would not have noticed the mistake.", "az": "Köməyin olmasaydı, səhvi görməzdim."}]}, {"level": "B2", "title": {"en": "Passive alternatives", "az": "Məchul növün alternativləri"}, "rule": {"en": "Sich lassen + infinitive expresses that something can be done. Sein + zu + infinitive can express necessity or possibility, depending on context.", "az": "Sich lassen + məsdər bir işin mümkün olduğunu bildirir. Sein + zu + məsdər kontekstdən asılı olaraq zərurət və ya imkan bildirə bilər."}, "examples": [{"de": "Das Problem lässt sich ohne neue Software lösen.", "en": "The problem can be solved without new software.", "az": "Problemi yeni proqram olmadan həll etmək mümkündür."}, {"de": "Die Unterlagen sind bis Freitag einzureichen.", "en": "The documents must be submitted by Friday.", "az": "Sənədlər cümə gününədək təqdim edilməlidir."}]}, {"level": "B2", "title": {"en": "Noun–verb combinations", "az": "İsim–fel birləşmələri"}, "rule": {"en": "Learn fixed combinations as units: eine Entscheidung treffen, Rücksicht nehmen auf and zur Verfügung stehen.", "az": "Sabit birləşmələri bütöv öyrən: eine Entscheidung treffen — qərar vermək; Rücksicht nehmen auf — nəzərə almaq; zur Verfügung stehen — istifadəyə hazır olmaq."}, "examples": [{"de": "Wir müssen heute eine Entscheidung treffen.", "en": "We must make a decision today.", "az": "Bu gün qərar verməliyik."}, {"de": "Bitte nehmen Sie Rücksicht auf die Nachbarn.", "en": "Please be considerate of the neighbours.", "az": "Zəhmət olmasa, qonşuları nəzərə alın."}]}, {"level": "B2", "title": {"en": "Nominal style", "az": "İsimlərlə ifadə"}, "rule": {"en": "Formal writing often uses nouns instead of subordinate clauses. Preserve the meaning and choose the preposition and case carefully.", "az": "Rəsmi yazıda budaq cümlə əvəzinə isimləşmiş ifadələr işlənə bilər. Mənanı qoru, sözönünü və halı diqqətlə seç."}, "examples": [{"de": "Wegen der Verspätung verpassen wir den Anschluss.", "en": "Because of the delay, we will miss our connection.", "az": "Gecikmə səbəbindən növbəti nəqliyyata çata bilməyəcəyik."}, {"de": "Nach Abschluss des Kurses sucht sie eine Stelle.", "en": "After completing the course, she will look for a job.", "az": "Kursu bitirdikdən sonra iş axtaracaq."}]}, {"level": "C1", "title": {"en": "Reported speech", "az": "Vasitəli nitq"}, "rule": {"en": "Konjunktiv I marks reported statements without automatically endorsing them. If its form is identical to the indicative, Konjunktiv II may make the report clearer.", "az": "Konjunktiv I başqasının sözlərini nəql edir; danışan bu fikri mütləq təsdiqləmir. Forma xəbər şəkli ilə eynidirsə, nəqli aydınlaşdırmaq üçün Konjunktiv II işlənə bilər."}, "examples": [{"de": "Die Sprecherin erklärte, die Lage sei stabil.", "en": "The spokesperson stated that the situation was stable.", "az": "Sözçü vəziyyətin sabit olduğunu bildirdi."}, {"de": "Er sagte, er habe die Unterlagen bereits geprüft.", "en": "He said he had already checked the documents.", "az": "O, sənədləri artıq yoxladığını dedi."}]}, {"level": "C1", "title": {"en": "Participial attributes", "az": "Feli sifət tərkibləri"}, "rule": {"en": "Extended participial attributes compress relative clauses. Participle I usually expresses an ongoing active process; Participle II often expresses a completed or passive one.", "az": "Geniş feli sifət tərkibləri təyin budaq cümləsini yığcamlaşdırır. Partizip I adətən davam edən aktiv hərəkəti, Partizip II isə tamamlanmış və ya məchul hərəkəti bildirir."}, "examples": [{"de": "Die gestern veröffentlichten Zahlen überraschten das Team.", "en": "The figures published yesterday surprised the team.", "az": "Dünən dərc olunan rəqəmlər komandanı təəccübləndirdi."}, {"de": "Die seit Jahren steigenden Mieten belasten viele Familien.", "en": "Rents that have been rising for years burden many families.", "az": "İllərdir artan kirayə haqları bir çox ailənin büdcəsini ağırlaşdırır."}]}, {"level": "C1", "title": {"en": "Hedging a claim", "az": "Fikri ehtiyatla ifadə etmək"}, "rule": {"en": "Distinguish certainty from inference. Dürfte often expresses a probability; könnte expresses a possibility. Evidence does not always justify a definite conclusion.", "az": "Qəti məlumatı ehtimaldan ayır. Dürfte çox vaxt güclü ehtimal, könnte isə mümkünlük bildirir. Dəlil hər zaman qəti nəticə çıxarmağa kifayət etmir."}, "examples": [{"de": "Die Nachfrage dürfte im Winter steigen.", "en": "Demand is likely to rise in winter.", "az": "Qışda tələbatın artacağı ehtimal olunur."}, {"de": "Der Unterschied könnte auf die Auswahl der Befragten zurückzuführen sein.", "en": "The difference might be due to how respondents were selected.", "az": "Fərq sorğu iştirakçılarının seçilmə üsulundan qaynaqlana bilər."}]}, {"level": "C1", "title": {"en": "Precise logical connections", "az": "Məntiqi əlaqələri dəqiq qurmaq"}, "rule": {"en": "Use sofern for a condition and zumal for an additional supporting reason. Choose connectors according to the logical relationship.", "az": "Şərt bildirmək üçün sofern, əlavə əsaslandırıcı səbəb üçün zumal işlənir. Bağlayıcını fikirlər arasındakı məntiqi əlaqəyə görə seç."}, "examples": [{"de": "Wir stimmen zu, sofern die Finanzierung gesichert ist.", "en": "We agree provided the funding is secured.", "az": "Maliyyələşmə təmin olunarsa, razılaşırıq."}, {"de": "Eine Verschiebung wäre sinnvoll, zumal wichtige Daten fehlen.", "en": "A postponement would make sense, especially as important data is missing.", "az": "Təxirə salmaq məqsədəuyğun olardı, xüsusən də vacib məlumatlar çatışmadığı üçün."}]}, {"level": "C1", "title": {"en": "Position and nuance", "az": "Mövqe və məna çalarları"}, "rule": {"en": "Small particles can change the intended contrast. Nicht nur ... sondern auch adds a second point; weder ... noch excludes both.", "az": "Kiçik sözlər qarşılaşdırmanın mənasını dəyişə bilər. Nicht nur ... sondern auch ikinci məqamı əlavə edir; weder ... noch hər ikisini inkar edir."}, "examples": [{"de": "Der Vorschlag ist nicht nur teuer, sondern auch schwer umzusetzen.", "en": "The proposal is not only expensive but also difficult to implement.", "az": "Təklif təkcə bahalı deyil, həm də həyata keçirilməsi çətindir."}, {"de": "Weder die Kosten noch die Dauer wurden genannt.", "en": "Neither the costs nor the duration were mentioned.", "az": "Nə xərclər, nə də müddət göstərildi."}]}];
const usageQuestions=[{"id": "usage-1", "level": "A1", "kind": "grammar", "q": "Heute ___ ich zu Hause.", "options": ["bleibe", "bleibst", "bleiben", "bleibt"], "correct": 0, "explanation": {"en": "Ich takes bleibe. Heute occupies the first position, so the verb comes next.", "az": "Ich ilə bleibe işlənir. Heute birinci yerdə olduğu üçün fel ikinci yerdə gəlir."}}, {"id": "usage-2", "level": "A1", "kind": "grammar", "q": "Ich kaufe ___ Apfel.", "options": ["ein", "einen", "einem", "einer"], "correct": 1, "explanation": {"en": "Apfel is masculine. A direct object uses the accusative: einen Apfel.", "az": "Apfel kişi cinsindədir. Birbaşa tamamlıq Akkusativdə olur: einen Apfel."}}, {"id": "usage-3", "level": "A1", "kind": "usage", "q": "Ich fahre ___ dem Bus zur Arbeit.", "options": ["mit", "für", "ohne", "um"], "correct": 0, "explanation": {"en": "Mit + dative describes the means of transport: mit dem Bus.", "az": "Nəqliyyat vasitəsi mit + Dativ ilə bildirilir: mit dem Bus — avtobusla."}}, {"id": "usage-4", "level": "A1", "kind": "form", "q": "Du ___ heute sehr müde aus.", "options": ["sehen", "seht", "siehst", "sieht"], "correct": 2, "explanation": {"en": "Sehen changes its vowel: du siehst. Aussehen separates: du siehst ... aus.", "az": "Sehen felində sait dəyişir: du siehst. Aussehen ayrılır: du siehst ... aus — görünürsən."}}, {"id": "usage-5", "level": "A1", "kind": "usage", "q": "Im Café: „Ich ___ gern einen Tee.“", "options": ["muss", "möchte", "kann", "bin"], "correct": 1, "explanation": {"en": "Möchte makes a polite request. Here it means I would like a tea.", "az": "Möchte nəzakətli istək bildirir. Burada mənası: bir çay istərdim."}}, {"id": "usage-6", "level": "A1", "kind": "form", "q": "Der Bus ___ um acht Uhr ab.", "options": ["fahren", "fährst", "fährt", "fahrt"], "correct": 2, "explanation": {"en": "Fahren becomes fährt with er/sie/es. Abfahren is separable.", "az": "Fahren felinin er/sie/es forması fährt-dir. Abfahren ayrılan feldir."}}, {"id": "usage-7", "level": "A1", "kind": "reading", "q": "Lena arbeitet von neun bis fünf. Danach kauft sie Brot. Was macht sie nach der Arbeit?", "options": ["Sie beginnt zu arbeiten.", "Sie kauft Brot.", "Sie fährt in Urlaub.", "Sie frühstückt."], "correct": 1, "explanation": {"en": "Danach refers to the time after her work ends.", "az": "Danach onun işdən çıxdığı vaxtdan sonranı bildirir."}}, {"id": "usage-8", "level": "A1", "kind": "reading", "q": "„Heute geschlossen. Morgen ab 10 Uhr geöffnet.“ Wann kannst du kommen?", "options": ["Heute um zehn.", "Heute Abend.", "Morgen vor zehn.", "Morgen um elf."], "correct": 3, "explanation": {"en": "The place opens tomorrow at ten; eleven is after opening time.", "az": "Məkan sabah saat onda açılır; on bir açılışdan sonradır."}}, {"id": "usage-9", "level": "A1", "kind": "grammar", "q": "___ du am Wochenende Zeit?", "options": ["Hast", "Hat", "Haben", "Habt"], "correct": 0, "explanation": {"en": "A yes/no question starts with the verb. Du uses hast.", "az": "Bəli/xeyr sualı fellə başlayır. Du ilə hast işlənir."}}, {"id": "usage-10", "level": "A1", "kind": "usage", "q": "Ich habe ___ Auto. Ich fahre mit dem Fahrrad.", "options": ["nicht", "kein", "keine", "keinen"], "correct": 1, "explanation": {"en": "Auto is neuter: ein Auto → kein Auto.", "az": "Auto orta cinsdədir: ein Auto → kein Auto."}}, {"id": "usage-11", "level": "A1", "kind": "form", "q": "Ein Kind, zwei ___.", "options": ["Kinds", "Kindern", "Kinder", "Kindes"], "correct": 2, "explanation": {"en": "The nominative/accusative plural of das Kind is die Kinder.", "az": "Das Kind sözünün Nominativ/Akkusativ cəm forması die Kinder-dir."}}, {"id": "usage-12", "level": "A1", "kind": "usage", "q": "Der Termin ist ___ Montag.", "options": ["im", "um", "am", "in"], "correct": 2, "explanation": {"en": "Use am with days of the week: am Montag.", "az": "Həftənin günləri ilə am işlənir: am Montag — bazar ertəsi."}}, {"id": "usage-13", "level": "A2", "kind": "grammar", "q": "Ich bleibe zu Hause, weil ich krank ___.", "options": ["bin", "ist", "sein", "bist"], "correct": 0, "explanation": {"en": "The conjugated verb goes to the end after weil; ich takes bin.", "az": "Weil-dən sonra təsriflənmiş fel sona keçir; ich ilə bin işlənir."}}, {"id": "usage-14", "level": "A2", "kind": "grammar", "q": "Das Buch liegt auf ___ Tisch.", "options": ["den", "der", "dem", "des"], "correct": 2, "explanation": {"en": "A location with auf takes dative. Der Tisch becomes dem Tisch.", "az": "Auf ilə yer bildirəndə Dativ işlənir. Der Tisch → dem Tisch."}}, {"id": "usage-15", "level": "A2", "kind": "usage", "q": "Kannst du ___ bitte helfen?", "options": ["mich", "mir", "mein", "meinen"], "correct": 1, "explanation": {"en": "Helfen takes dative: jemandem helfen.", "az": "Helfen Dativ tələb edir: jemandem helfen — kiməsə kömək etmək."}}, {"id": "usage-16", "level": "A2", "kind": "form", "q": "Wir sind gestern nach Berlin ___.", "options": ["gefahrt", "gefahren", "gefahrenen", "fahren"], "correct": 1, "explanation": {"en": "The participle is gefahren. Travel to a destination uses sein here.", "az": "Partizip II forması gefahren-dir. Burada istiqamətə hərəkət sein ilə işlənir."}}, {"id": "usage-17", "level": "A2", "kind": "usage", "q": "Ich stelle die Flasche ___ den Tisch.", "options": ["auf", "bei", "mit", "seit"], "correct": 0, "explanation": {"en": "A destination with auf takes accusative: auf den Tisch.", "az": "Auf ilə istiqamət bildiriləndə Akkusativ işlənir: auf den Tisch — masanın üstünə."}}, {"id": "usage-18", "level": "A2", "kind": "form", "q": "Sie hat den Schlüssel im Garten ___.", "options": ["gefindet", "findet", "gefunden", "fand"], "correct": 2, "explanation": {"en": "Finden has the participle gefunden; fand is the simple past.", "az": "Finden felinin Partizip II forması gefunden-dir; fand sadə keçmiş zamandır."}}, {"id": "usage-19", "level": "A2", "kind": "reading", "q": "Mira wollte mit dem Rad fahren. Weil es regnet, nimmt sie die Bahn. Warum ändert sie ihren Plan?", "options": ["Ihr Fahrrad ist kaputt.", "Der Zug ist billiger.", "Wegen des Wetters.", "Sie hat das Fahrrad verkauft."], "correct": 2, "explanation": {"en": "The text gives rain as the reason; a broken bicycle is not mentioned.", "az": "Mətndə səbəb kimi yağış göstərilir; velosipedin xarab olması deyilmir."}}, {"id": "usage-20", "level": "A2", "kind": "reading", "q": "„Bitte bringen Sie Ihren Ausweis mit. Sie müssen nichts bezahlen.“ Was ist nötig?", "options": ["Eine Zahlung vor dem Termin.", "Ein Ausweis.", "Ein neues Foto.", "Eine Fahrkarte."], "correct": 1, "explanation": {"en": "Bringen Sie ... mit asks you to bring your identity document.", "az": "Bringen Sie ... mit şəxsiyyət sənədini özünlə gətirməyi tələb edir."}}, {"id": "usage-21", "level": "A2", "kind": "grammar", "q": "Meine Wohnung ist kleiner ___ deine.", "options": ["wie", "als", "ob", "wenn"], "correct": 1, "explanation": {"en": "A comparative uses als. Equality uses so ... wie.", "az": "Müqayisə dərəcəsi ilə als, bərabərlik üçün so ... wie işlənir."}}, {"id": "usage-22", "level": "A2", "kind": "usage", "q": "Ich interessiere mich ___ Musik.", "options": ["an", "über", "für", "von"], "correct": 2, "explanation": {"en": "The fixed construction is sich interessieren für + accusative.", "az": "Sabit birləşmə sich interessieren für + Akkusativ-dir: bir şeylə maraqlanmaq."}}, {"id": "usage-23", "level": "A2", "kind": "form", "q": "Gestern ___ ich keine Zeit.", "options": ["habe", "hatte", "hätte", "haben"], "correct": 1, "explanation": {"en": "Hatte is the simple past of haben. Hätte describes an imagined situation.", "az": "Hatte haben felinin sadə keçmiş formasıdır. Hätte isə xəyali vəziyyət bildirir."}}, {"id": "usage-24", "level": "A2", "kind": "usage", "q": "Wir wohnen ___ zwei Jahren hier.", "options": ["vor", "für", "seit", "bis"], "correct": 2, "explanation": {"en": "Seit describes an ongoing situation that began in the past.", "az": "Seit keçmişdə başlayıb davam edən vəziyyətin müddətini bildirir."}}, {"id": "usage-25", "level": "B1", "kind": "grammar", "q": "Das ist die Frau, ___ ich geholfen habe.", "options": ["die", "der", "den", "deren"], "correct": 1, "explanation": {"en": "Helfen takes dative, so the feminine relative pronoun is der.", "az": "Helfen Dativ tələb edir; qadın cinsində nisbi əvəzlik der olur."}}, {"id": "usage-26", "level": "B1", "kind": "grammar", "q": "Wenn ich mehr Zeit ___, würde ich öfter lesen.", "options": ["habe", "hatte", "hätte", "hätte gehabt"], "correct": 2, "explanation": {"en": "Hätte expresses an unreal present condition.", "az": "Hätte indiki zamana aid real olmayan şərt bildirir."}}, {"id": "usage-27", "level": "B1", "kind": "usage", "q": "Er nimmt ___ einem Sprachkurs teil.", "options": ["auf", "an", "für", "über"], "correct": 1, "explanation": {"en": "Teilnehmen an takes dative: an einem Kurs teilnehmen.", "az": "Teilnehmen an + Dativ: kursda iştirak etmək."}}, {"id": "usage-28", "level": "B1", "kind": "form", "q": "Sie hat sich für die Ausbildung ___.", "options": ["entschied", "entscheiden", "entschieden", "geentscheidet"], "correct": 2, "explanation": {"en": "The participle of entscheiden is entschieden, without ge-.", "az": "Entscheiden felinin Partizip II forması ge- olmadan entschieden-dir."}}, {"id": "usage-29", "level": "B1", "kind": "usage", "q": "Ich freue mich ___ den Urlaub nächste Woche.", "options": ["über", "auf", "von", "mit"], "correct": 1, "explanation": {"en": "Sich freuen auf looks forward to a future event; über responds to something already real.", "az": "Sich freuen auf gələcək hadisəni səbirsizliklə gözləməkdir; über isə artıq mövcud olana sevinməkdir."}}, {"id": "usage-30", "level": "B1", "kind": "form", "q": "Früher ___ ich jeden Tag mit dem Rad zur Schule.", "options": ["fuhr", "fährt", "gefahren", "fahre"], "correct": 0, "explanation": {"en": "Fuhr is the first-person simple past of fahren.", "az": "Fuhr fahren felinin birinci şəxsdə sadə keçmiş formasıdır."}}, {"id": "usage-31", "level": "B1", "kind": "reading", "q": "Der Kurs ist voll. Wer sich jetzt anmeldet, kommt auf die Warteliste und erhält Nachricht, falls ein Platz frei wird. Ist ein Platz garantiert?", "options": ["Ja, nach der Anmeldung.", "Ja, ab nächster Woche.", "Nein, nur bei einer Absage wird möglicherweise ein Platz frei.", "Nein, der Kurs findet nicht statt."], "correct": 2, "explanation": {"en": "The condition falls ein Platz frei wird means admission depends on an available place.", "az": "Falls ein Platz frei wird şərti qəbulun boş yer yaranmasından asılı olduğunu göstərir."}}, {"id": "usage-32", "level": "B1", "kind": "reading", "q": "Jonas fährt früher los, um den Anschluss nicht zu verpassen. Sein erster Zug ist oft verspätet. Was möchte er vermeiden?", "options": ["Zu früh am Bahnhof zu sein.", "Die nächste Verbindung zu verlieren.", "Eine Fahrkarte zu kaufen.", "Mit dem Zug zu reisen."], "correct": 1, "explanation": {"en": "Den Anschluss verpassen means missing the connecting service.", "az": "Den Anschluss verpassen növbəti nəqliyyat vasitəsinə çata bilməmək deməkdir."}}, {"id": "usage-33", "level": "B1", "kind": "grammar", "q": "Ich lerne Deutsch, ___ in Deutschland arbeiten zu können.", "options": ["damit", "weil", "um", "dass"], "correct": 2, "explanation": {"en": "The subject is the same, and the infinitive clause uses um ... zu.", "az": "İcraçı eynidir və məsdər tərkibi um ... zu ilə qurulur."}}, {"id": "usage-34", "level": "B1", "kind": "usage", "q": "Kann ich mich ___ deine Hilfe verlassen?", "options": ["an", "auf", "über", "für"], "correct": 1, "explanation": {"en": "Sich verlassen auf + accusative means to rely on.", "az": "Sich verlassen auf + Akkusativ — kiməsə və ya nəyəsə arxalanmaq."}}, {"id": "usage-35", "level": "B1", "kind": "form", "q": "Die Rechnung wurde gestern ___.", "options": ["bezahlt", "bezahlte", "gebezahlt", "bezahlen"], "correct": 0, "explanation": {"en": "Passive uses werden plus the participle bezahlt. Be- prevents ge-.", "az": "Məchul növdə werden + bezahlt işlənir. Be- ön şəkilçisi olan feldə ge- əlavə edilmir."}}, {"id": "usage-36", "level": "B1", "kind": "usage", "q": "Ich möchte mich ___ die Verspätung entschuldigen.", "options": ["bei", "für", "an", "mit"], "correct": 1, "explanation": {"en": "Apologise for something with für; apologise to a person with bei.", "az": "Nəyəsə görə üzr istəmək üçün für, kimdənsə üzr istəmək üçün bei işlənir."}}, {"id": "usage-37", "level": "B2", "kind": "grammar", "q": "___ es stark regnete, fand das Konzert statt.", "options": ["Trotzdem", "Obwohl", "Deshalb", "Wegen"], "correct": 1, "explanation": {"en": "Obwohl introduces a subordinate clause; trotzdem would need a main-clause structure.", "az": "Obwohl budaq cümlə yaradır; trotzdem ilə baş cümlə quruluşu lazım olardı."}}, {"id": "usage-38", "level": "B2", "kind": "grammar", "q": "Wenn ich früher losgefahren ___, hätte ich den Zug erreicht.", "options": ["hätte", "bin", "wäre", "würde"], "correct": 2, "explanation": {"en": "The past unreal form of a sein verb uses wäre + participle.", "az": "Sein ilə işlənən felin keçmişə aid Konjunktiv II forması wäre + Partizip II-dir."}}, {"id": "usage-39", "level": "B2", "kind": "usage", "q": "Wir müssen heute eine Entscheidung ___.", "options": ["machen", "treffen", "stellen", "legen"], "correct": 1, "explanation": {"en": "The established combination is eine Entscheidung treffen.", "az": "Sabit birləşmə eine Entscheidung treffen-dir: qərar vermək."}}, {"id": "usage-40", "level": "B2", "kind": "form", "q": "Die Gespräche sind an der Finanzierung ___.", "options": ["gescheitert", "gescheitern", "scheiterten", "gescheiterten"], "correct": 0, "explanation": {"en": "Scheitern uses sein in the perfect: ist gescheitert.", "az": "Scheitern Perfektdə sein ilə işlənir: ist gescheitert — uğursuz olub."}}, {"id": "usage-41", "level": "B2", "kind": "usage", "q": "Die Studie weist ___ erhebliche Unterschiede hin.", "options": ["an", "mit", "auf", "für"], "correct": 2, "explanation": {"en": "Hinweisen auf + accusative means to point out or indicate.", "az": "Hinweisen auf + Akkusativ — nəyəsə diqqət çəkmək və ya onu göstərmək."}}, {"id": "usage-42", "level": "B2", "kind": "form", "q": "Die Firma hat ihre Ausgaben deutlich ___.", "options": ["gesunken", "gesenkt", "sank", "sinken"], "correct": 1, "explanation": {"en": "Senken is transitive: reduce something. Sinken means fall without a direct object.", "az": "Senken — nəyisə azaltmaq; sinken — öz-özünə azalmaq və ya enmək."}}, {"id": "usage-43", "level": "B2", "kind": "reading", "q": "In einem Betrieb sinken nach Einführung flexibler Arbeitszeiten die Fehltage. Gleichzeitig wird die Personalzahl erhöht. Was lässt sich daraus sicher ableiten?", "options": ["Flexible Zeiten sind die einzige Ursache.", "Mehr Personal führt immer zu weniger Fehltagen.", "Die Fehltage gingen zurück; die Ursache ist damit noch nicht eindeutig geklärt.", "Die Arbeitszeiten hatten keinen Einfluss."], "correct": 2, "explanation": {"en": "Two changes happened together. The figures alone do not isolate their effects.", "az": "İki dəyişiklik eyni vaxtda baş verib. Rəqəmlər onların təsirini ayrı-ayrılıqda müəyyən etmir."}}, {"id": "usage-44", "level": "B2", "kind": "reading", "q": "„Der Vorschlag ist grundsätzlich sinnvoll; seine Umsetzung setzt jedoch zusätzliche Mittel voraus.“ Welche Haltung wird ausgedrückt?", "options": ["Uneingeschränkte Zustimmung.", "Ablehnung des gesamten Vorschlags.", "Zustimmung mit einer Voraussetzung.", "Unsicherheit über das Thema."], "correct": 2, "explanation": {"en": "Grundsätzlich sinnvoll is positive; setzt ... voraus adds a funding condition.", "az": "Grundsätzlich sinnvoll müsbət qiymətləndirmədir; setzt ... voraus maliyyə şərti əlavə edir."}}, {"id": "usage-45", "level": "B2", "kind": "grammar", "q": "Das Problem lässt sich schnell ___.", "options": ["lösen", "gelöst", "zu lösen", "löste"], "correct": 0, "explanation": {"en": "Sich lassen + infinitive is a passive alternative expressing possibility.", "az": "Sich lassen + məsdər mümkünlük bildirən məchul növ alternatividir."}}, {"id": "usage-46", "level": "B2", "kind": "usage", "q": "Bitte nehmen Sie Rücksicht ___ die anderen Gäste.", "options": ["an", "für", "auf", "bei"], "correct": 2, "explanation": {"en": "Rücksicht nehmen auf + accusative means to be considerate of.", "az": "Rücksicht nehmen auf + Akkusativ — başqalarını nəzərə almaq."}}, {"id": "usage-47", "level": "B2", "kind": "form", "q": "Er hat die neue Regel zunächst ___.", "options": ["missversteht", "missverstanden", "gemissverstanden", "missverstand"], "correct": 1, "explanation": {"en": "The participle is missverstanden; missverstand is the simple past.", "az": "Partizip II missverstanden-dir; missverstand sadə keçmiş zamandır."}}, {"id": "usage-48", "level": "B2", "kind": "usage", "q": "Eine Verschiebung kommt für uns nicht in ___.", "options": ["Frage", "Antwort", "Rede", "Wort"], "correct": 0, "explanation": {"en": "Nicht in Frage kommen means not to be an option.", "az": "Nicht in Frage kommen — mümkün seçim sayılmamaq, qəbul edilə bilməmək."}}, {"id": "usage-49", "level": "C1", "kind": "grammar", "q": "Die Sprecherin erklärte, die Lage ___ stabil.", "options": ["ist gewesen", "sei", "wäre gewesen", "sein"], "correct": 1, "explanation": {"en": "Sei is Konjunktiv I and marks the statement as reported speech.", "az": "Sei Konjunktiv I formasıdır və fikrin nəql edildiyini göstərir."}}, {"id": "usage-50", "level": "C1", "kind": "grammar", "q": "Die gestern ___ Ergebnisse werden nun geprüft.", "options": ["veröffentlichende", "veröffentlichten", "veröffentlichen", "veröffentlichter"], "correct": 1, "explanation": {"en": "The results were published: Participle II plus the plural adjective ending -en after die.", "az": "Nəticələr dərc olunub: Partizip II və die-dən sonra cəm sifət sonluğu -en işlənir."}}, {"id": "usage-51", "level": "C1", "kind": "usage", "q": "Der Unterschied ist ___ die Auswahl der Befragten zurückzuführen.", "options": ["an", "für", "auf", "bei"], "correct": 2, "explanation": {"en": "Zurückzuführen sein auf + accusative attributes something to a cause.", "az": "Zurückzuführen sein auf + Akkusativ — nəyinsə səbəbi ilə izah olunmaq, ondan qaynaqlanmaq."}}, {"id": "usage-52", "level": "C1", "kind": "form", "q": "Das Unternehmen hat sich dem Druck ___.", "options": ["gebeugt", "gebogen", "beugte", "bog"], "correct": 0, "explanation": {"en": "Sich beugen means yield: sich dem Druck beugen. Gebogen belongs to biegen.", "az": "Sich dem Druck beugen — təzyiqə boyun əymək. Gebogen isə biegen felinə aiddir."}}, {"id": "usage-53", "level": "C1", "kind": "usage", "q": "Die Daten geben keinen ___ auf einen Zusammenhang.", "options": ["Verweis", "Auftrag", "Anlass", "Hinweis"], "correct": 3, "explanation": {"en": "Einen Hinweis auf etwas geben means to provide an indication of it.", "az": "Einen Hinweis auf etwas geben — nəyinsə mövcudluğuna işarə etmək."}}, {"id": "usage-54", "level": "C1", "kind": "form", "q": "Sie hat die Folgen ihrer Entscheidung sorgfältig ___.", "options": ["abgewägt", "abgewogen", "abwiegte", "abgewiegt"], "correct": 1, "explanation": {"en": "The standard participle of abwägen is abgewogen.", "az": "Abwägen felinin standart Partizip II forması abgewogen-dir: diqqətlə ölçüb-biçmək."}}, {"id": "usage-55", "level": "C1", "kind": "reading", "q": "Eine Kennzahl steigt, nachdem die Definition der erfassten Fälle erweitert wurde. Die Leitung wertet dies als Leistungszuwachs. Was ist der zentrale Einwand?", "options": ["Kennzahlen sind grundsätzlich nutzlos.", "Der Anstieg könnte auf der veränderten Erfassung beruhen.", "Die Leistung muss gesunken sein.", "Die Definition hat sich nicht geändert."], "correct": 1, "explanation": {"en": "Changing what is counted can change the figure without changing underlying performance.", "az": "Sayılma meyarının dəyişməsi real fəaliyyət dəyişmədən göstəricini artıra bilər."}}, {"id": "usage-56", "level": "C1", "kind": "reading", "q": "„Die Erklärung ist plausibel, vermag die beobachteten Unterschiede jedoch nicht vollständig zu erklären.“ Was wird eingeschränkt?", "options": ["Die Existenz der Unterschiede.", "Die Verständlichkeit des Textes.", "Die Reichweite der Erklärung.", "Die Möglichkeit weiterer Forschung."], "correct": 2, "explanation": {"en": "Plausible does not mean sufficient: the author limits how much the explanation accounts for.", "az": "İnandırıcı olmaq kifayət etmək demək deyil: müəllif izahın əhatə dairəsini məhdudlaşdırır."}}, {"id": "usage-57", "level": "C1", "kind": "grammar", "q": "Wir stimmen zu, ___ die Finanzierung gesichert ist.", "options": ["zumal", "sofern", "obgleich", "sodass"], "correct": 1, "explanation": {"en": "Sofern introduces the condition under which agreement is given.", "az": "Sofern razılığın verilməsi üçün tələb olunan şərti bildirir."}}, {"id": "usage-58", "level": "C1", "kind": "usage", "q": "Diese Schlussfolgerung lässt sich aus den Daten nicht ___.", "options": ["ableiten", "anleiten", "einleiten", "begleiten"], "correct": 0, "explanation": {"en": "Eine Schlussfolgerung aus Daten ableiten means to infer a conclusion from data.", "az": "Eine Schlussfolgerung aus Daten ableiten — məlumatlardan nəticə çıxarmaq."}}, {"id": "usage-59", "level": "C1", "kind": "form", "q": "Die vorgelegten Belege haben die Behauptung ___.", "options": ["widerlegt", "wiederlegt", "gewiderlegt", "widerlegen"], "correct": 0, "explanation": {"en": "Widerlegen means refute and forms widerlegt; wieder- would mean again.", "az": "Widerlegen — təkzib etmək; Partizip II widerlegt-dir. Wieder- isə yenidən mənası verir."}}, {"id": "usage-60", "level": "C1", "kind": "usage", "q": "Die Maßnahme steht im Widerspruch ___ den vereinbarten Zielen.", "options": ["mit", "zu", "auf", "gegen"], "correct": 1, "explanation": {"en": "Im Widerspruch stehen zu + dative means to contradict.", "az": "Im Widerspruch stehen zu + Dativ — ziddiyyət təşkil etmək."}}];
const strongerStoryQuestions={"story-1": [{"q": "Warum fragt Ali Anna nach einem Wort?", "options": ["Er möchte seine Aufgabe verstehen.", "Er will eine Pause machen.", "Er sucht den Weg nach Hause."], "correct": 0, "explanation": {"en": "Anna explains the unfamiliar word so Ali can continue his task.", "az": "Anna tanış olmayan sözü izah edir ki, Ali tapşırığına davam edə bilsin."}}, {"q": "Was zeigt Alis Plan für den nächsten Tag?", "options": ["Er will die Wörter nur abschreiben.", "Er möchte die Wörter aktiv benutzen.", "Er möchte nicht mehr mit Kollegen sprechen."], "correct": 1, "explanation": {"en": "He intends to use the three words in conversation, not only record them.", "az": "O, üç sözü yalnız yazmaq yox, söhbətdə işlətmək istəyir."}}], "story-2": [{"q": "Warum entscheidet Mira nicht sofort?", "options": ["Der Vermieter sagt den Termin ab.", "Sie kann die Miete nicht bezahlen.", "Die kürzere Fahrt muss gegen den Lärm abgewogen werden."], "correct": 2, "explanation": {"en": "The flat is closer to work, but traffic noise conflicts with her wish for quiet.", "az": "Mənzil işə yaxındır, amma yol səsi onun sakitlik istəyinə uyğun gəlmir."}}, {"q": "Was erfährt man über den Vermieter?", "options": ["Er verschweigt den Verkehrslärm.", "Er spricht offen über die volle Straße.", "Er bietet eine kostenlose Wohnung an."], "correct": 1, "explanation": {"en": "He honestly confirms that the street is busy during the week.", "az": "O, küçənin həftə içi sıx olduğunu dürüstcə təsdiqləyir."}}], "story-3": [{"q": "Welche zwei Dinge führen zur Verspätung?", "options": ["Ein verlorenes Ticket und Regen.", "Spätes Aufstehen und ein verspäteter Bus.", "Ein falsches Gleis und ein kaputter Zug."], "correct": 1, "explanation": {"en": "Ben gets up late and the bus is also late.", "az": "Ben gec oyanır, üstəlik avtobus da gecikir."}}, {"q": "Warum prüft Ben sein Ticket erneut?", "options": ["Er möchte wissen, ob es für die andere Verbindung gilt.", "Er will den Namen seines Freundes ändern.", "Er hat das Ticket noch nicht gekauft."], "correct": 0, "explanation": {"en": "He checks whether his existing ticket is valid for the alternative journey.", "az": "Mövcud biletinin alternativ səfər üçün keçərli olub-olmadığını yoxlayır."}}], "story-4": [{"q": "Warum ändert Nora ihren Einkauf?", "options": ["Ihre Freundin möchte nur Brot essen.", "Sie möchte ein Gericht ohne Milchprodukte kochen.", "Im Supermarkt gibt es kein Gemüse."], "correct": 1, "explanation": {"en": "She adapts the meal to her friend's diet so everyone can eat the same dish.", "az": "Hamının eyni yeməyi yeyə bilməsi üçün rəfiqəsinin qidalanmasına uyğun dəyişiklik edir."}}, {"q": "Welches Verhalten spart Geld?", "options": ["Zwei kleine Brote statt eines großen kaufen.", "Alles ohne Preisvergleich kaufen.", "Das günstigere große Brot wählen."], "correct": 2, "explanation": {"en": "The large loaf costs less than two small loaves.", "az": "Böyük çörək iki kiçik çörəkdən ucuzdur."}}], "story-5": [{"q": "Weshalb ist der Abend am Ende doch positiv?", "options": ["Jonas lernt seinen Nachbarn besser kennen.", "Jonas findet einen neuen Schlüssel auf der Straße.", "Seine Mitbewohnerin kommt sofort."], "correct": 0, "explanation": {"en": "The tea leads to a conversation and a plan for a shared outing.", "az": "Çay söhbətə və birlikdə gəzinti planına səbəb olur."}}, {"q": "Was haben Jonas und sein Nachbar gemeinsam?", "options": ["Sie arbeiten in derselben Firma.", "Sie wandern beide gern.", "Sie haben beide keinen Schlüssel."], "correct": 1, "explanation": {"en": "They discover their shared interest in hiking.", "az": "Hər ikisinin yürüş etməyi sevdiyini öyrənirlər."}}], "story-6": [{"q": "Was belegt Leas Beispiel aus dem Projekt?", "options": ["Sie vermeidet jede Verantwortung.", "Sie trifft Entscheidungen ohne Informationen.", "Sie sucht bei Unsicherheit gemeinsam nach einer Lösung."], "correct": 2, "explanation": {"en": "When information was missing, she involved colleagues instead of guessing alone.", "az": "Məlumat çatışmayanda təkbaşına təxmin etmək əvəzinə həmkarlarını cəlb edib."}}, {"q": "Welche Schlussfolgerung ist durch den Text gedeckt?", "options": ["Lea hat die Stelle sicher bekommen.", "Lea ist mit ihrem Auftreten zufrieden, kennt aber das Ergebnis nicht.", "Die Leiterin hat Lea abgelehnt."], "correct": 1, "explanation": {"en": "She is satisfied with the interview, but the hiring decision is still unknown.", "az": "Müsahibədən razıdır, amma işə qəbul qərarı hələ məlum deyil."}}], "story-7": [{"q": "Wodurch bemerkt Emil den Fehler?", "options": ["Der Karton ist leer.", "Auf dem Karton steht ein anderer Name.", "Sein Buch ist beschädigt."], "correct": 1, "explanation": {"en": "The name and address show that the first parcel belongs to someone else.", "az": "Ad və ünvan ilk bağlamanın başqasına aid olduğunu göstərir."}}, {"q": "Was ändert Emil künftig?", "options": ["Er prüft den Empfängernamen früher.", "Er bestellt nie wieder Bücher.", "Er öffnet fremde Pakete sofort."], "correct": 0, "explanation": {"en": "His lesson from the mistake is to check the name immediately.", "az": "Bu səhvdən çıxardığı nəticə adı dərhal yoxlamaqdır."}}], "story-8": [{"q": "Wodurch wird Saras Sprechangst kleiner?", "options": ["Sie vermeidet jede Frage.", "Die anderen interessieren sich für ihre Geschichte.", "Sie spricht nur noch ihre Muttersprache."], "correct": 1, "explanation": {"en": "The genuine interest of her classmates shifts her attention toward communication.", "az": "Sinif yoldaşlarının marağı onun diqqətini ünsiyyətə yönəldir."}}, {"q": "Warum sollen die Treffen wiederholt werden?", "options": ["Weil einmaliges Auswendiglernen genügt.", "Weil die Lehrerin täglich kontrolliert.", "Weil regelmäßige Gespräche Sicherheit geben."], "correct": 2, "explanation": {"en": "Sara notices that frequent small conversations build confidence.", "az": "Sara müntəzəm qısa söhbətlərin özünəinam yaratdığını görür."}}], "story-9": [{"q": "Warum repariert David das Fahrrad nicht sofort?", "options": ["Er möchte sein wichtiges Gespräch erreichen.", "Er will das Fahrrad verkaufen.", "Die Werkstatt ist dauerhaft geschlossen."], "correct": 0, "explanation": {"en": "The time pressure makes the bus the practical option that morning.", "az": "Vaxt azlığı həmin səhər avtobusu praktik seçim edir."}}, {"q": "Was bedeutet der gespeicherte Busfahrplan für ihn?", "options": ["Er gibt das Radfahren auf.", "Er kennt eine Alternative für künftige Probleme.", "Er möchte als Busfahrer arbeiten."], "correct": 1, "explanation": {"en": "Having a fallback helps him feel calmer about another breakdown.", "az": "Alternativ variantın olması növbəti nasazlıq barədə onu rahatlaşdırır."}}], "story-10": [{"q": "Warum funktioniert Aylins Plan?", "options": ["Er berücksichtigt mehrere unterschiedliche Wünsche.", "Er überträgt alle Aufgaben einer Person.", "Er verbietet Kindern den Garten."], "correct": 0, "explanation": {"en": "The plan makes room for play, vegetables and flowers.", "az": "Plan oyun, tərəvəz və güllər üçün yer ayırır."}}, {"q": "Was ist für Aylin der wichtigste Erfolg?", "options": ["Die Zahl der Blumen.", "Dass niemand mehr Urlaub macht.", "Dass eine Gemeinschaft entstanden ist."], "correct": 2, "explanation": {"en": "She values the stronger relationships and shared problem-solving.", "az": "O, münasibətlərin möhkəmlənməsini və problemlərin birlikdə həllini dəyərləndirir."}}], "story-11": [{"q": "Woher weiß Frau Berger vermutlich, was im Paket ist?", "options": ["Sie hat die Lampe benutzt.", "Auf dem Paket ist ein Bild der Lampe.", "Samir hat ihr vorher geschrieben."], "correct": 1, "explanation": {"en": "The package itself displays a large picture of the lamp.", "az": "Bağlamanın üzərində lampanın böyük şəkli var."}}, {"q": "Warum bietet Samir am nächsten Morgen Hilfe an?", "options": ["Er braucht noch einen Zettel.", "Er möchte die Lampe zurückgeben.", "Er möchte sich für die Hilfe erkenntlich zeigen."], "correct": 2, "explanation": {"en": "His offer to carry the shopping bag follows her helpful gesture.", "az": "Alış-veriş çantasını daşımaq təklifi onun köməyinə qarşılıqdır."}}], "story-12": [{"q": "Wie löst Leyla das Problem mit dem Salz?", "options": ["Sie lässt jeden selbst nachsalzen.", "Sie kocht für Paul eine neue Suppe.", "Sie gibt allen mehr Salz."], "correct": 0, "explanation": {"en": "Putting salt on the table lets each person choose.", "az": "Duzu masaya qoymaq hər kəsə özü seçim etmək imkanı verir."}}, {"q": "Warum freut sich die Freundin besonders?", "options": ["Die Suppe enthält kein Fleisch.", "Sie bekommt einen eigenen Topf.", "Paul bezahlt die Einkäufe."], "correct": 0, "explanation": {"en": "The friend does not eat meat, and the soup suits her diet.", "az": "Rəfiqə ət yemir və şorba onun qidalanmasına uyğundur."}}], "story-13": [{"q": "Was verändert sich für Murad durch den Gesprächskreis?", "options": ["Er erkennt Lernen auch als gemeinsamen Austausch.", "Er gibt die Prüfungsvorbereitung auf.", "Er findet seine Wohnung plötzlich ruhig."], "correct": 0, "explanation": {"en": "The group broadens his idea of learning beyond reading alone.", "az": "Qrup onun öyrənmə anlayışını təkbaşına oxumaqdan kənara çıxarır."}}, {"q": "Welche Aussage über die Bibliothek stimmt?", "options": ["Murad muss sein Handy abgeben.", "Sie bietet ihm Ruhe und einen Hinweis auf Sprechpraxis.", "Dort darf er keine Pause machen."], "correct": 1, "explanation": {"en": "He finds both a quiet workspace and an advertisement for the conversation group.", "az": "O, həm sakit iş yeri, həm də danışıq qrupu elanı tapır."}}], "story-14": [{"q": "Warum ist Anna nach der Reparatur stolz?", "options": ["Sie hat das teuerste Fahrrad gekauft.", "Sie hat selbst an der Reparatur mitgewirkt.", "Sie hat Jens alles allein machen lassen."], "correct": 1, "explanation": {"en": "Helping with the repair gives her a sense of achievement.", "az": "Təmirdə iştirak etmək ona nailiyyət hissi verir."}}, {"q": "Was zeigt ihre Frage nach dem nächsten Termin?", "options": ["Sie möchte ihre Reparaturkenntnisse erweitern.", "Sie glaubt, dass die Bremsen noch kaputt sind.", "Sie verlangt ihr Geld zurück."], "correct": 0, "explanation": {"en": "She wants to learn how to change a tyre next.", "az": "Növbəti dəfə təkər dəyişməyi öyrənmək istəyir."}}], "story-15": [{"q": "Warum sind die ersten Ergebnisse nicht eindeutig?", "options": ["Die Testphase wurde nie begonnen.", "Alle Beschäftigten arbeiten weniger sorgfältig.", "Projektzeiten und persönliche Belastung entwickeln sich unterschiedlich."], "correct": 2, "explanation": {"en": "Some projects improve, while others slow down; experiences also vary.", "az": "Bəzi layihələr sürətlənir, digərləri ləngiyir; şəxsi təcrübələr də fərqlidir."}}, {"q": "Welche Vorstellung von Erfolg setzt sich durch?", "options": ["Ausschließlich die Zahl abgeschlossener Projekte zählt.", "Ergebnisse und Arbeitsbedingungen müssen gemeinsam betrachtet werden.", "Nur die freie Zeit der Leitung ist entscheidend."], "correct": 1, "explanation": {"en": "The final evaluation includes outcomes and the employees' experiences.", "az": "Yekun qiymətləndirmə həm nəticələri, həm də işçilərin təcrübəsini əhatə edir."}}], "story-16": [{"q": "Welche Wirkung hat die Beobachtung des Parkplatzes?", "options": ["Sie ersetzt jede weitere Diskussion.", "Sie macht einen differenzierteren Kompromiss möglich.", "Sie beweist, dass kein Kunde ein Auto besitzt."], "correct": 1, "explanation": {"en": "The observations shift the debate toward partial changes, not total removal.", "az": "Müşahidələr müzakirəni tam ləğvdən qismən dəyişikliklərə yönəldir."}}, {"q": "Warum ist die spätere Überprüfung wichtig?", "options": ["Sie ermöglicht eine Bewertung der tatsächlichen Auswirkungen.", "Sie garantiert steigende Umsätze.", "Sie verhindert jede Begrünung."], "correct": 0, "explanation": {"en": "The agreement includes checking actual effects rather than relying on predictions alone.", "az": "Razılaşma yalnız proqnozlara deyil, real təsirlərin yoxlanmasına da əsaslanır."}}], "story-17": [{"q": "Was war die eigentliche Ursache von Noras Druck?", "options": ["Eine ausdrücklich angeordnete Nachtschicht.", "Eine nie geklärte Erwartung an ihre Erreichbarkeit.", "Eine technische Pflicht, sofort zu antworten."], "correct": 1, "explanation": {"en": "She assumed immediate replies were expected; her manager had not required them.", "az": "Dərhal cavabın gözləndiyini güman edirdi; rəhbər bunu tələb etməmişdi."}}, {"q": "Welche Unterscheidung löst das Problem?", "options": ["Zwischen dringenden und gewöhnlichen Nachrichten.", "Zwischen deutschen und internationalen Kollegen.", "Zwischen bezahlten und unbezahlten Projekten."], "correct": 0, "explanation": {"en": "A separate channel for urgent matters lets ordinary messages wait.", "az": "Təcili məsələlər üçün ayrı kanal adi mesajların gözləməsinə imkan verir."}}], "story-18": [{"q": "Was begünstigt die ungeprüfte Übernahme des Vorschlags?", "options": ["Die bessere Begründung jeder automatischen Einstufung.", "Der geringere Aufwand gegenüber einer Abweichung.", "Das Verbot menschlicher Entscheidungen."], "correct": 1, "explanation": {"en": "Accepting takes one click; disagreeing requires a long explanation.", "az": "Qəbul etmək bir klikdir; fərqli qərar isə uzun əsaslandırma tələb edir."}}, {"q": "Welche Aussage trifft die Pointe des Textes?", "options": ["Formale Zuständigkeit allein garantiert keine wirksame Kontrolle.", "Jede technische Einstufung ist falsch.", "Mehr Zahlen ersetzen die Prüfung."], "correct": 0, "explanation": {"en": "Responsibility requires time, usable information and real discretion.", "az": "Məsuliyyət vaxt, istifadə edilə bilən məlumat və real qərar sərbəstliyi tələb edir."}}], "story-19": [{"q": "Wie verändern die zusätzlichen Quellen das Bild?", "options": ["Sie widerlegen ausnahmslos jede Aussage des Besitzers.", "Sie ergänzen und verschieben die Perspektive auf denselben Zeitraum.", "Sie beweisen, dass Archive vollständig sind."], "correct": 1, "explanation": {"en": "The sources do not contradict every detail but highlight different experiences.", "az": "Mənbələr hər detalı təkzib etmir, fərqli təcrübələri önə çıxarır."}}, {"q": "Welche Funktion hat die ausdrücklich benannte Unsicherheit?", "options": ["Sie soll Forschung als unmöglich darstellen.", "Sie ersetzt Quellen durch Meinungen.", "Sie macht Entstehung und Grenzen des Wissens nachvollziehbar."], "correct": 2, "explanation": {"en": "Selin explains how evidence supports knowledge and where gaps remain.", "az": "Selin bilginin dəlillərdən necə yarandığını və boşluqların harada qaldığını izah edir."}}], "story-20": [{"q": "Welcher Fehlanreiz entsteht durch reine Reichweitenmessung?", "options": ["Schwierige Fälle könnten zugunsten hoher Zahlen vermieden werden.", "Jede Initiative müsste weniger Menschen helfen.", "Fallbeschreibungen würden automatisch genauer."], "correct": 0, "explanation": {"en": "Rewarding only reach can encourage avoiding people who need intensive support.", "az": "Yalnız əhatə dairəsini mükafatlandırmaq çox dəstək tələb edən insanlardan yayınmağa sövq edə bilər."}}, {"q": "Was leistet das neue Verfahren?", "options": ["Es schafft vollständige Vergleichbarkeit.", "Es verbindet Zahlen mit Kontext und bleibt überprüfbar.", "Es verzichtet auf jede quantitative Angabe."], "correct": 1, "explanation": {"en": "Numbers remain, but case descriptions and feedback add context.", "az": "Rəqəmlər saxlanılır, amma hal təsvirləri və rəylər kontekst əlavə edir."}}]};
