stories.push(...[{"id": "story-21", "level": "A1", "title": "Ein Kaffee vor der Arbeit", "text": "Es ist Montag. Sara arbeitet heute im Büro. Vor der Arbeit geht sie in ein kleines Café. Sie hat noch zwanzig Minuten Zeit. Am Fenster ist ein Tisch frei. Sara setzt sich und liest die Karte.\n\nEin Mann kommt an den Tisch. „Was möchten Sie?“ Sara bestellt einen Kaffee und ein Brot mit Käse. Der Kaffee ist heiß. Sara wartet kurz und schaut aus dem Fenster. Draußen fährt ein Bus vorbei.\n\nUm halb neun bezahlt sie. Das Büro ist nicht weit. Sara geht zu Fuß. Vor der Tür trifft sie ihre Kollegin. „Guten Morgen!“, sagt Sara. Zusammen gehen sie hinein.", "questions": [{"q": "Was bestellt Sara?", "options": ["Tee und Suppe", "Kaffee und ein Brot mit Käse", "Wasser und Kuchen"], "correct": 1, "explanation": {"en": "She orders coffee and bread with cheese.", "az": "O, qəhvə və pendirli çörək sifariş edir."}}, {"q": "Warum kann sie noch im Café sitzen?", "options": ["Sie hat vor der Arbeit noch Zeit.", "Sie arbeitet nicht mehr.", "Das Büro ist geschlossen."], "correct": 0, "explanation": {"en": "She has twenty minutes before work.", "az": "İşdən əvvəl iyirmi dəqiqə vaxtı var."}}, {"q": "Wie kommt sie zum Büro?", "options": ["Mit dem Bus", "Mit dem Auto", "Zu Fuß"], "correct": 2, "explanation": {"en": "The office is nearby, so she walks.", "az": "Ofis yaxın olduğu üçün piyada gedir."}}]}, {"id": "story-22", "level": "A1", "title": "Ein freier Samstag", "text": "Am Samstag muss Tom nicht arbeiten. Er steht um neun Uhr auf und macht das Fenster auf. Das Wetter ist gut. Tom möchte heute im Park spazieren gehen. Er ruft seine Freundin Anna an. Anna hat am Vormittag keine Zeit. Sie muss noch einkaufen.\n\n„Treffen wir uns um zwei?“, fragt Tom. Anna sagt ja. Tom frühstückt und liest ein Buch. Um halb zwei nimmt er seine Jacke und geht zur Haltestelle. Der Bus kommt sofort.\n\nAnna wartet schon am Eingang zum Park. Sie hat zwei Flaschen Wasser dabei. Tom und Anna gehen langsam durch den Park und sprechen über ihre Woche. Danach essen sie zusammen. Tom findet: Ein freier Tag muss nicht teuer sein.", "questions": [{"q": "Warum treffen sie sich erst am Nachmittag?", "options": ["Tom muss arbeiten.", "Anna muss vorher einkaufen.", "Der Park ist morgens geschlossen."], "correct": 1, "explanation": {"en": "Anna needs to shop in the morning.", "az": "Anna səhər alış-veriş etməlidir."}}, {"q": "Wann wollen sie sich treffen?", "options": ["Um neun Uhr", "Um halb zwei", "Um zwei Uhr"], "correct": 2, "explanation": {"en": "Um zwei means two o’clock, here in the afternoon.", "az": "Um zwei burada günorta saat ikini bildirir."}}, {"q": "Was bringt Anna mit?", "options": ["Wasser für beide", "Ein Buch für Tom", "Zwei Jacken"], "correct": 0, "explanation": {"en": "She brings two bottles of water.", "az": "O, iki şüşə su gətirir."}}]}]);
